// Get canvas element and its 2D context
const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");

// Set canvas size to match window dimensions
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

// Configuration constants
const TOTAL_CIRCLES = 50; // Number of circles to generate
const CIRCLES = []; // Array to store circle objects
const FLOW_SPEED_X = 1; // Horizontal movement speed
const TRAIL_LENGTH = 30; // Max length of each circle's trail
const TRAIL_FADE = 0.05; // Opacity fade rate for trails

// Circle class to manage properties and behavior
class Circle {
  constructor() {
    this.posX = Math.random() * canvas.width; // Initial X position
    this.posY = Math.random() * canvas.height; // Initial Y position
    this.radius = Math.random() * 20 + 10; // Random radius between 10-30
    this.speed = Math.random() * 2 + 1; // Speed of wave oscillation
    this.waveAmplitude = Math.random() * 5 + 2; // Height of vertical wave
    this.wavePhase = Math.random() * Math.PI * 2; // Starting point in wave cycle
    this.color = `rgba(0, 128, 255, ${Math.random() * 0.5 + 0.2})`; // Semi-transparent blue
    this.trail = []; // Array to store trail positions
  }

  // Update circle's position and wave motion
  update() {
    this.wavePhase += this.speed * 0.01; // Increment phase for oscillation
    this.posY += Math.sin(this.wavePhase) * this.waveAmplitude; // Vertical wave motion
  }

  // Draw the circle and its trail
  draw() {
    const perspective = 1 - this.posY / canvas.height; // Depth effect based on Y position
    ctx.globalAlpha = perspective * (1 - TRAIL_FADE); // Adjust opacity with perspective

    // Draw trail circles with fading size and opacity
    for (let i = 0; i < this.trail.length; i++) {
      const trailPerspective = 1 - this.trail[i].y / canvas.height;
      const trailRadius = Math.max(
        this.radius * trailPerspective * (1 - i / this.trail.length),
        0
      );
      ctx.beginPath();
      ctx.arc(this.trail[i].x, this.trail[i].y, trailRadius, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw current circle
    const currentRadius = Math.max(this.radius * perspective, 0);
    ctx.beginPath();
    ctx.arc(this.posX, this.posY, currentRadius, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();

    // Update trail with current position
    this.trail.push({ x: this.posX, y: this.posY });
    if (this.trail.length > TRAIL_LENGTH) {
      this.trail.shift(); // Remove oldest trail point
    }
  }
}

// Initialize circles
for (let i = 0; i < TOTAL_CIRCLES; i++) {
  CIRCLES.push(new Circle());
}

// Animation loop
function animate() {
  ctx.clearRect(0, 0, canvas.width, canvas.height); // Clear canvas each frame

  for (const circle of CIRCLES) {
    circle.update(); // Update position and wave
    circle.draw(); // Render circle and trail

    // Move circle horizontally and reset if off-screen
    circle.posX += FLOW_SPEED_X;
    if (circle.posX > canvas.width + circle.radius) {
      circle.posX = -circle.radius;
    }
  }

  requestAnimationFrame(animate); // Queue next frame
}

// Start the animation
animate();
